INSERT INTO `freelancerprofile` VALUES (1,3,'MERN stack developer with 4 years of experience building scalable web apps. Delivered 30+ projects for clients across India and Southeast Asia.',1800.00,'INTERMEDIATE','Pune, Maharashtra','FULL_TIME',NULL,'2026-08-24 16:02:42.193','2026-08-24 16:02:42.193'),(2,54,'Updated bio for production testing.',1500.00,'INTERMEDIATE','Ahmedabad, Gujarat','FULL_TIME',NULL,'2026-08-24 16:02:42.264','2026-08-26 14:26:57.429'),(3,55,'Google-certified UX designer focused on user research and information architecture. Prototyping expert in Figma and Adobe XD with 5 years experience.',1600.00,'INTERMEDIATE','Bengaluru, Karnataka','FULL_TIME',NULL,'2026-08-24 16:02:42.334','2026-08-24 16:02:42.334'),(4,56,'Node.js and Python backend engineer with deep expertise in REST and GraphQL APIs, PostgreSQL, MongoDB. 6 years building high-throughput fintech systems.',2200.00,'EXPERT','Hyderabad, Telangana','PART_TIME',NULL,'2026-08-24 16:02:42.402','2026-08-24 16:02:42.402'),(5,57,'Flutter and React Native developer building cross-platform apps. Published 8 apps on Play Store and App Store with combined 50k+ downloads.',2000.00,'INTERMEDIATE','Kochi, Kerala','FULL_TIME',NULL,'2026-08-24 16:02:42.470','2026-08-24 16:02:42.470'),(6,58,'AWS Solutions Architect Associate certified. Specialises in serverless architectures, CI/CD pipelines, and infrastructure-as-code with Terraform.',2800.00,'EXPERT','Chennai, Tamil Nadu','PART_TIME',NULL,'2026-08-24 16:02:42.538','2026-08-24 16:02:42.538'),(7,59,'Brand identity and visual communication designer with 7 years creating logos, packaging, and marketing collateral for Indian and global brands.',1200.00,'EXPERT','Mumbai, Maharashtra','FULL_TIME',NULL,'2026-08-24 16:02:42.607','2026-08-24 16:02:42.607'),(8,60,'Data professional with expertise in Python, SQL, Power BI, and Tableau. Turned raw data into actionable insights for 15+ FMCG and retail companies.',1700.00,'INTERMEDIATE','Bengaluru, Karnataka','FULL_TIME',NULL,'2026-08-24 16:02:42.675','2026-08-24 16:02:42.675'),(9,61,'Performance marketing specialist managing Google Ads, Meta Ads, and SEO for D2C brands. Managed ad budgets exceeding Rs. 50 lakh per month.',1300.00,'INTERMEDIATE','Delhi, NCR','FULL_TIME',NULL,'2026-08-24 16:02:42.744','2026-08-24 16:02:42.744'),(10,62,'Kubernetes and Docker expert. Designed and managed multi-cluster EKS environments and automated deployments for SaaS products. CKA certified.',3000.00,'EXPERT','Noida, Uttar Pradesh','PART_TIME',NULL,'2026-08-24 16:02:42.813','2026-08-24 16:02:42.813'),(11,63,'SEO-driven content strategist and long-form writer for SaaS, healthtech, and edtech sectors. 500+ published articles and white papers.',900.00,'INTERMEDIATE','Hyderabad, Telangana','FULL_TIME',NULL,'2026-08-24 16:02:42.881','2026-08-24 16:02:42.881'),(12,64,'ML engineer with expertise in NLP, computer vision, and recommendation systems. Built production ML pipelines on GCP for major e-commerce clients.',3500.00,'EXPERT','Chennai, Tamil Nadu','PART_TIME',NULL,'2026-08-24 16:02:42.950','2026-08-24 16:02:42.950'),(13,65,'Custom WordPress theme and plugin developer. Built 80+ websites for SMEs, NGOs, and educational institutions across India.',800.00,'ENTRY','Jaipur, Rajasthan','FULL_TIME',NULL,'2026-08-24 16:02:43.018','2026-08-24 16:02:43.018'),(14,66,'Shopify and WooCommerce expert. Manages end-to-end store setup, product listings, payment integration, and conversion optimisation for retail brands.',1100.00,'INTERMEDIATE','Surat, Gujarat','FULL_TIME',NULL,'2026-08-24 16:02:43.087','2026-08-24 16:02:43.087'),(15,67,'Premiere Pro and After Effects wizard creating reels, explainer videos, and branded content for YouTube channels and OTT productions.',1000.00,'INTERMEDIATE','Kolkata, West Bengal','FULL_TIME',NULL,'2026-08-24 16:02:43.156','2026-08-24 16:02:43.156'),(16,68,'OSCP-certified penetration tester conducting VAPT for fintech and healthcare platforms. Helped 20+ firms achieve ISO 27001 compliance.',4000.00,'EXPERT','Bengaluru, Karnataka','PART_TIME',NULL,'2026-08-24 16:02:43.224','2026-08-24 16:02:43.224'),(17,69,'Native Android developer (Kotlin/Java) building fintech and healthcare apps. 5 years experience with complex integrations including UPI and Aadhaar APIs.',2100.00,'INTERMEDIATE','Nashik, Maharashtra','FULL_TIME',NULL,'2026-08-24 16:02:43.291','2026-08-24 16:02:43.291'),(18,70,'BA with 8 years bridging technical and business teams. Specialises in requirement gathering, user stories, and process mapping for ERP and CRM implementations.',2000.00,'EXPERT','Chennai, Tamil Nadu','PART_TIME',NULL,'2026-08-24 16:02:43.360','2026-08-24 16:02:43.360'),(19,71,'Swift and SwiftUI developer with 4 apps on the App Store. Strong in MVVM architecture, Core Data, and HealthKit integrations.',2400.00,'INTERMEDIATE','Patna, Bihar','FULL_TIME',NULL,'2026-08-24 16:02:43.429','2026-08-24 16:02:43.429'),(20,72,'Managed Instagram, LinkedIn, and Twitter growth for 30+ brands across lifestyle, food, and B2B SaaS niches. Grew accounts from 0 to 100k+ followers.',750.00,'ENTRY','Thiruvananthapuram, Kerala','FULL_TIME',NULL,'2026-08-24 16:02:43.497','2026-08-24 16:02:43.497'),(21,73,'Oracle and MySQL DBA with 9 years managing mission-critical databases for banking and insurance sector clients. Expert in performance tuning and disaster recovery.',2600.00,'EXPERT','Lucknow, Uttar Pradesh','PART_TIME',NULL,'2026-08-24 16:02:43.565','2026-08-24 16:02:43.565'),(22,74,NULL,NULL,'ENTRY',NULL,'FULL_TIME',NULL,'2026-09-25 07:35:39.761','2026-09-25 07:35:39.761');
