INSERT INTO `project` VALUES (1,30,1,'Luxury Fashion E-commerce Portal','Build a full-featured luxury fashion e-commerce portal for ModeHaus with product catalogues, wishlists, Razorpay payment gateway integration, and a curated editorial blog section. The site must be mobile-first, support Hindi and English, and load within 2 seconds on Indian 4G networks.',85000.00,'2026-11-15 00:00:00.000','EXPERT','OPEN','2026-08-24 16:12:39.230','2026-08-24 16:12:39.230'),(2,29,1,'Online Vehicle Service Booking Platform','Develop a web platform for AutoCare Pune allowing customers to book car service slots, select service packages, receive SMS reminders, and track service status in real time. Admin panel required for managing appointments and technician assignments.',55000.00,'2026-10-30 00:00:00.000','INTERMEDIATE','OPEN','2026-08-24 16:12:39.253','2026-08-24 16:12:39.253'),(3,4,1,'Vernacular Learning Management System','Build a scalable LMS for BrightWave Edtech supporting live classes, recorded lessons, multilingual content in Hindi, Marathi and Tamil, student progress tracking, and certificate generation. Must integrate with Zoom API for live sessions.',120000.00,'2026-12-31 00:00:00.000','EXPERT','OPEN','2026-08-24 16:12:39.268','2026-08-24 16:12:39.268'),(4,15,1,'SaaS Customer Dashboard with Usage Analytics','Design and develop a multi-tenant SaaS dashboard for CloudQube Technologies showing API usage, billing summaries, service health metrics, and subscription management. Must support role-based access for end customers and internal admins.',95000.00,'2026-11-01 00:00:00.000','EXPERT','IN_PROGRESS','2026-08-24 16:12:39.287','2026-08-24 16:12:39.287'),(5,17,1,'Farmer-to-Buyer B2B Marketplace','Build a web marketplace for AgroLink Agritech connecting farmers in rural Maharashtra and UP with urban grocery wholesalers. Requires crop listing, bulk order management, MSP-aware pricing engine, and regional language support.',75000.00,'2026-11-20 00:00:00.000','INTERMEDIATE','OPEN','2026-08-24 16:12:39.305','2026-08-24 16:12:39.305'),(6,39,1,'Client Portal for Cybersecurity Firm','Develop a secure client portal for CyberSec India where clients can view VAPT reports, track remediation status, download compliance certificates, and raise support tickets. Must enforce 2FA and session timeout policies.',68000.00,'2026-10-15 00:00:00.000','EXPERT','OPEN','2026-08-24 16:12:39.321','2026-08-24 16:12:39.321'),(7,37,1,'Patient Portal for Diagnostic Chain','Build a web-based patient portal for MedPulse Diagnostics where patients can book tests online, view reports, receive WhatsApp notifications, and manage family health records. Aadhaar-based login preferred.',72000.00,'2026-12-01 00:00:00.000','INTERMEDIATE','OPEN','2026-08-24 16:12:39.336','2026-08-24 16:12:39.336'),(8,35,1,'B2B MSME Supplier Marketplace','Build a regional B2B web marketplace for UPBizz connecting MSME manufacturers in Kanpur and Agra with distributors. Features: supplier verification, RFQ system, logistics integration, GST invoice generation.',90000.00,'2026-12-15 00:00:00.000','EXPERT','OPEN','2026-08-24 16:12:39.351','2026-08-24 16:12:39.351'),(9,42,1,'Smart Energy Meter Management Portal','Develop a web portal for SmartGrid Technologies allowing utility companies to manage smart meter deployments, view consumption data, detect anomalies, and generate billing reports. Real-time data via WebSockets.',110000.00,'2027-01-31 00:00:00.000','EXPERT','OPEN','2026-08-24 16:12:39.369','2026-08-24 16:12:39.369'),(10,38,1,'Heritage Hotel Direct Booking Engine','Build a direct booking engine for LuxuryStay Hotels in Shimla with room availability calendar, seasonal pricing engine, Razorpay integration, automated confirmation emails, and an admin panel for reservation management.',48000.00,'2026-10-01 00:00:00.000','INTERMEDIATE','COMPLETED','2026-08-24 16:12:39.392','2026-08-24 16:12:39.392'),(11,20,2,'Cloud Kitchen Food Ordering App','Build a cross-platform mobile app for FlavourFusion Cloud Kitchen with live menu, real-time order tracking, loyalty points, and push notifications. Must integrate with Zomato-style delivery partner API and support UPI, card, and COD payment modes.',65000.00,'2026-11-10 00:00:00.000','INTERMEDIATE','OPEN','2026-08-24 16:12:39.405','2026-08-24 16:12:39.405'),(12,13,2,'Pharma Inventory Management Mobile App','Develop an Android app for PharmaBridge Distributors to manage drug inventory, scan barcodes, generate purchase orders, track expiry dates, and produce daily stock reports. Must sync with the existing ERP via REST APIs.',55000.00,'2026-10-25 00:00:00.000','INTERMEDIATE','OPEN','2026-08-24 16:12:39.418','2026-08-24 16:12:39.418'),(13,33,2,'Kerala Tourism Experience App','Build a travel app for Kerala Horizon Tours showcasing curated backwater and wildlife packages, offline maps, local guide booking, itinerary management, and multilingual support in Malayalam and English.',58000.00,'2026-11-30 00:00:00.000','INTERMEDIATE','OPEN','2026-08-24 16:12:39.437','2026-08-24 16:12:39.437'),(14,24,2,'Corporate Wellness Subscription App','Develop a mobile wellness app for HealthRoots Wellness offering personalised meal plans, hydration reminders, yoga videos, BMI tracking, and monthly health reports. Corporate HR dashboard for bulk employee management.',70000.00,'2026-12-15 00:00:00.000','INTERMEDIATE','OPEN','2026-08-24 16:12:39.452','2026-08-24 16:12:39.452'),(15,23,2,'B2B Marble Catalogue and Order App','Build an Android app for Royal Marble & Granite enabling export clients to browse high-resolution stone catalogues, request samples, place bulk orders, and track shipments. Offline mode required for trade show use.',42000.00,'2026-10-20 00:00:00.000','ENTRY','OPEN','2026-08-24 16:12:39.476','2026-08-24 16:12:39.476'),(16,51,2,'Subscription-Based Online Yoga App','Develop a cross-platform yoga app for YogaWave Online Studio with live class scheduling, session recordings library, guided meditation, instructor booking, subscription billing via Razorpay, and community chat.',62000.00,'2026-11-25 00:00:00.000','INTERMEDIATE','OPEN','2026-08-24 16:12:39.491','2026-08-24 16:12:39.491'),(17,9,3,'Investment Advisory App UI Redesign','Redesign the mobile and web UI for BlueChip Invest Advisory platform. Must convey trust and professionalism. Deliverables: user research report, wireframes, high-fidelity Figma prototype, design system, and developer handoff specs.',40000.00,'2026-10-10 00:00:00.000','EXPERT','IN_PROGRESS','2026-08-24 16:12:39.504','2026-08-24 16:12:39.504'),(18,14,3,'Interior Design Studio Website UX','Design the user experience for Studio Neha Designs website showcasing portfolio projects, enabling online consultations booking, and a mood-board creation tool. Aesthetic must reflect contemporary Indian interior design sensibilities.',28000.00,'2026-09-30 00:00:00.000','INTERMEDIATE','COMPLETED','2026-08-24 16:12:39.516','2026-08-24 16:12:39.516'),(19,6,3,'Organic Brand Mobile App UX Overhaul','Conduct a full UX audit and redesign of the GreenLeaf Organics mobile shopping app. Focus on reducing checkout abandonment, improving product discovery with AI-powered recommendations, and a fresh earth-toned visual identity.',35000.00,'2026-10-20 00:00:00.000','INTERMEDIATE','OPEN','2026-08-24 16:12:39.526','2026-08-24 16:12:39.526'),(20,16,3,'OTT Streaming Platform UI Design','Design the UI for MediaWala Entertainment OTT platform targeting tier-2 Indian cities. Requires homepage, content discovery page, video player, subscription flow, and responsive layouts for TV, tablet and mobile.',52000.00,'2026-11-05 00:00:00.000','EXPERT','OPEN','2026-08-24 16:12:39.540','2026-08-24 16:12:39.540'),(21,44,3,'Startup Analytics Dashboard UI Design','Design a clean, data-dense analytics dashboard UI for PixelPitch Analytics used by startup founders to visualise KPIs, investor metrics, and runway. Deliverables: Figma file with auto-layout components and interactive prototype.',32000.00,'2026-10-01 00:00:00.000','INTERMEDIATE','OPEN','2026-08-24 16:12:39.553','2026-08-24 16:12:39.553'),(22,46,4,'Ethnic Fashion Brand Identity Package','Create a complete brand identity for Punjabi Couture House: logo, colour palette, typography guide, swing tags, packaging, shopping bag design, and a social media template kit. Must reflect the vibrancy of Punjabi heritage and contemporary fashion.',25000.00,'2026-09-25 00:00:00.000','INTERMEDIATE','OPEN','2026-08-24 16:12:39.563','2026-08-24 16:12:39.563'),(23,48,4,'Print-on-Demand Product Templates Library','Design a library of 50 customisable product templates for ePrintX covering mugs, t-shirts, phone covers, notebooks, and posters. Templates must be export-ready in high resolution and follow Indian gifting occasions and festivals.',30000.00,'2026-10-30 00:00:00.000','INTERMEDIATE','OPEN','2026-08-24 16:12:39.573','2026-08-24 16:12:39.573'),(24,43,4,'Gourmet Spice Brand Packaging Design','Design premium packaging for Saffron Spice Co. product line covering 15 SKUs including spice pouches, gift boxes, and travel-size tins. Visual language should convey artisan quality and Indian origin. Print-ready files required.',22000.00,'2026-09-20 00:00:00.000','INTERMEDIATE','COMPLETED','2026-08-24 16:12:39.579','2026-08-24 16:12:39.579'),(25,28,4,'Handmade Jewellery Brand Visual Identity','Create a premium visual identity for Artisan & Craft handmade jewellery brand: logo, brand book, product photography style guide, Etsy banner templates, and Instagram highlight cover designs.',18000.00,'2026-09-15 00:00:00.000','ENTRY','COMPLETED','2026-08-24 16:12:39.586','2026-08-24 16:12:39.586'),(26,31,5,'Telecom Network Anomaly Detection System','Build an ML-powered anomaly detection system for India Telecom Infrastructure to identify network faults, predict outages 30 minutes in advance, and auto-escalate alerts. Must process 1 million events per hour from network probes.',150000.00,'2027-02-28 00:00:00.000','EXPERT','OPEN','2026-08-24 16:12:39.592','2026-08-24 16:12:39.592'),(27,19,5,'Jewellery Inventory Demand Forecasting','Develop a demand forecasting model for Diamond Display Jewellers to predict seasonal stock requirements across their 12 retail locations. Input: 3 years of POS data. Output: weekly restocking recommendations per store per SKU.',80000.00,'2026-12-01 00:00:00.000','EXPERT','OPEN','2026-08-24 16:12:39.608','2026-08-24 16:12:39.608'),(28,21,5,'Fintech Credit Risk Scoring Model','Build a credit risk scoring ML model for CalcuttaTech Finserv using alternative data sources including GST filing history, UPI transaction patterns, and social signals. Must output an explainable risk score with confidence intervals.',130000.00,'2027-01-15 00:00:00.000','EXPERT','OPEN','2026-08-24 16:12:39.624','2026-08-24 16:12:39.624'),(29,40,5,'Commodity Price Prediction Dashboard','Build a Power BI-backed dashboard with a Python ML model predicting wheat, rice, and maize price movements for GrainMarket India based on mandi arrival data, rainfall indices, and MSP notifications.',60000.00,'2026-11-01 00:00:00.000','INTERMEDIATE','OPEN','2026-08-24 16:12:39.641','2026-08-24 16:12:39.641'),(30,42,5,'Energy Consumption Pattern Analysis','Analyse energy consumption data from 50,000 smart meters for SmartGrid Technologies to identify peak load patterns, detect meter tampering, and segment consumers into behavioural clusters for targeted conservation programs.',70000.00,'2026-11-30 00:00:00.000','EXPERT','OPEN','2026-08-24 16:12:39.657','2026-08-24 16:12:39.657'),(31,15,6,'Multi-Region AWS Infrastructure Setup','Design and implement a multi-region AWS infrastructure for CloudQube Technologies covering Mumbai and Singapore regions. Deliverables: Terraform IaC scripts, VPC setup, EKS cluster, RDS Multi-AZ, CloudFront CDN, and full runbook.',100000.00,'2026-11-15 00:00:00.000','EXPERT','OPEN','2026-08-24 16:12:39.672','2026-08-24 16:12:39.672'),(32,39,6,'CI/CD Pipeline for Security Tool Suite','Set up a complete CI/CD pipeline for CyberSec India internal security tooling using GitHub Actions, Docker, and Kubernetes on AWS EKS. Must include automated SAST/DAST scans, secrets management via AWS Secrets Manager, and blue-green deployments.',75000.00,'2026-10-31 00:00:00.000','EXPERT','OPEN','2026-08-24 16:12:39.690','2026-08-24 16:12:39.690'),(33,31,6,'Telecom On-Premise to Cloud Migration','Migrate 30 legacy on-premise applications for India Telecom Infrastructure to AWS cloud with zero downtime. Strategy: lift-and-shift Phase 1, re-platforming Phase 2. Deliverables: migration assessment, execution runbooks, post-migration monitoring setup.',200000.00,'2027-03-31 00:00:00.000','EXPERT','OPEN','2026-08-24 16:12:39.708','2026-08-24 16:12:39.708'),(34,32,6,'IoT Device Management on AWS','Set up AWS IoT Core infrastructure for SolarPlus Energy to manage 10,000 solar inverter IoT devices. Includes device provisioning, MQTT message routing, time-series storage on DynamoDB, and CloudWatch alerting dashboard.',85000.00,'2026-12-15 00:00:00.000','EXPERT','OPEN','2026-08-24 16:12:39.723','2026-08-24 16:12:39.723'),(35,7,7,'Fashion Brand Google & Meta Ads Campaign','Plan and execute a 3-month paid marketing campaign for TrendSetters Fashion House covering Google Shopping Ads, Meta catalogue ads, and Instagram Reels promotions targeting urban Indian women aged 18–35. Budget: ₹8 lakh. KPI: 3x ROAS.',35000.00,'2026-10-01 00:00:00.000','INTERMEDIATE','OPEN','2026-08-24 16:12:39.739','2026-08-24 16:12:39.739'),(36,8,7,'Ayurveda Brand Digital Marketing Strategy','Develop a 6-month digital marketing strategy for AyurWellness Pvt. Ltd. covering SEO, content marketing, influencer outreach, YouTube channel launch, and WhatsApp Business campaigns. Focus on tier-2 cities in Kerala and Tamil Nadu.',28000.00,'2026-10-15 00:00:00.000','INTERMEDIATE','OPEN','2026-08-24 16:12:39.751','2026-08-24 16:12:39.751'),(37,49,7,'Festival Season E-commerce Marketing Push','Execute a Diwali and Christmas seasonal marketing campaign for Southern Sweets Co. covering Swiggy Instamart promotions, Google Local Ads, WhatsApp bulk messaging, and Instagram content calendar. Target: 40% revenue growth over last festive season.',22000.00,'2026-10-05 00:00:00.000','ENTRY','OPEN','2026-08-24 16:12:39.764','2026-08-24 16:12:39.764'),(38,43,7,'Spice Brand Amazon & Organic SEO Campaign','Improve Amazon product ranking and organic SEO for Saffron Spice Co. across 15 product pages. Deliverables: keyword research, Amazon A+ content, backend search terms, on-page SEO optimisation for the brand website, and monthly reporting.',18000.00,'2026-10-10 00:00:00.000','ENTRY','COMPLETED','2026-08-24 16:12:39.778','2026-08-24 16:12:39.778'),(39,36,7,'Art Gallery Online Presence Growth','Build and execute a digital presence strategy for Pintura Arts Gallery on Instagram, Pinterest, and Google. Includes gallery content calendar, influencer partnerships, Google My Business optimisation, and a monthly email newsletter.',15000.00,'2026-10-01 00:00:00.000','ENTRY','OPEN','2026-08-24 16:12:39.791','2026-08-24 16:12:39.791'),(40,34,8,'Author Website Blog Content - 20 Articles','Write 20 SEO-optimised blog articles (1000–1500 words each) for author Shweta Iyer covering topics in Indian fiction, creative writing tips, self-publishing, and Tamil literature. Tone: literary, warm, and conversational.',12000.00,'2026-10-20 00:00:00.000','INTERMEDIATE','OPEN','2026-08-24 16:12:39.804','2026-08-24 16:12:39.804'),(41,8,8,'Ayurveda Product Description Copywriting','Write compelling product descriptions for 40 Ayurvedic health products for AyurWellness Pvt. Ltd. Each description must include benefits, ingredients, usage instructions, and SEO-friendly keywords. Must comply with AYUSH advertising guidelines.',16000.00,'2026-09-30 00:00:00.000','INTERMEDIATE','OPEN','2026-08-24 16:12:39.814','2026-08-24 16:12:39.814'),(42,53,8,'Children\'s Book Series Content','Write 5 short illustrated children\'s stories (800–1200 words each) for StoryMint Publications targeting children aged 6–10. Themes: Indian festivals, folk tales, and STEM adventures. Stories must pass a Flesch-Kincaid grade level check.',20000.00,'2026-10-25 00:00:00.000','INTERMEDIATE','OPEN','2026-08-24 16:12:39.823','2026-08-24 16:12:39.823'),(43,47,8,'Folk Music Tour Press Kit & Web Copy','Write a full press kit and website copy for BaulGuru Productions including artist bios, tour programme descriptions, festival pitches, and a bilingual (English/Bengali) about page. Tone: poetic and culturally resonant.',10000.00,'2026-09-28 00:00:00.000','ENTRY','OPEN','2026-08-24 16:12:39.830','2026-08-24 16:12:39.830'),(44,16,9,'OTT Platform Promotional Trailer Package','Produce 5 promotional trailers (60–90 seconds each) for MediaWala Entertainment new original web series. Deliverables: motion graphics, colour grading, subtitle integration, and platform-specific exports for YouTube, Instagram and JioCinema.',45000.00,'2026-10-15 00:00:00.000','EXPERT','OPEN','2026-08-24 16:12:39.838','2026-08-24 16:12:39.838'),(45,47,9,'Folk Music Concert Highlight Reel','Edit a 5-minute concert highlight reel for BaulGuru Productions from 8 hours of multi-camera footage. Include colour grading, audio mixing, animated lower thirds with artist names, and a short 30-second Instagram cut.',18000.00,'2026-10-05 00:00:00.000','INTERMEDIATE','OPEN','2026-08-24 16:12:39.847','2026-08-24 16:12:39.847'),(46,7,9,'Fashion Brand Reels Content Package','Produce 12 short-form video reels (15–30 seconds) per month for TrendSetters Fashion House for Instagram and YouTube Shorts. Includes concept ideation, motion text overlays, trending audio integration, and branded end screens.',24000.00,'2026-10-01 00:00:00.000','INTERMEDIATE','IN_PROGRESS','2026-08-24 16:12:39.857','2026-08-24 16:12:39.857'),(47,4,9,'Explainer Videos for Edtech Platform','Produce 10 animated explainer videos (2–3 minutes each) for BrightWave Edtech courses. Topics range from mathematics to Indian history. Style: 2D motion graphics with voiceover. Deliverables: English and Hindi versions of each video.',60000.00,'2026-11-30 00:00:00.000','EXPERT','OPEN','2026-08-24 16:12:39.870','2026-08-24 16:12:39.870'),(48,12,10,'Handloom Export Shopify Store Setup','Set up and configure a Shopify store for CraftsByHand Exports with 200+ product listings, international shipping configuration, multi-currency support, export compliance pages, and SEO-optimised category pages for US and UK markets.',32000.00,'2026-10-15 00:00:00.000','INTERMEDIATE','OPEN','2026-08-24 16:12:39.886','2026-08-24 16:12:39.886'),(49,6,10,'Organic Food D2C WooCommerce Store','Build and optimise a WooCommerce store for GreenLeaf Organics with subscription boxes, auto-ship recurring orders, product review integration, loyalty points, and WhatsApp order confirmation. GST-compliant invoicing required.',40000.00,'2026-11-01 00:00:00.000','INTERMEDIATE','OPEN','2026-08-24 16:12:39.895','2026-08-24 16:12:39.895'),(50,26,10,'South Indian Textile Brand Online Store','Launch a WooCommerce store for TextileSouth Pvt. Ltd. with regional language support, saree draping video guides, virtual try-on mockup tool, cash-on-delivery option, and return management portal. PAN India delivery integration required.',38000.00,'2026-10-30 00:00:00.000','INTERMEDIATE','OPEN','2026-08-24 16:12:39.907','2026-08-24 16:12:39.907'),(51,18,10,'Silk Saree Export Bilingual Online Store','Build a bilingual (Kannada + English) Shopify store for SilkRoute Exports Pvt. Ltd. targeted at NRI customers. Includes high-resolution product zoom, fabric comparison tool, bulk order request form, and PayPal + Razorpay integration.',35000.00,'2026-10-20 00:00:00.000','INTERMEDIATE','OPEN','2026-08-24 16:12:39.919','2026-08-24 16:12:39.919'),(52,50,10,'Authenticated Gemstone B2B Trading Platform','Build a Shopify-based B2B platform for GemstoneRaj with gemologist certificate uploads, 360-degree stone videos, bulk pricing tiers, verified buyer onboarding, and wire-transfer payment workflows targeting international gem trade buyers.',55000.00,'2026-11-15 00:00:00.000','EXPERT','OPEN','2026-08-24 16:12:39.928','2026-08-24 16:12:39.928'),(53,5,11,'Logistics ERP Module Customisation','Customise the existing open-source ERP (Odoo) for InfraLogix India by building a custom Fleet Management module covering vehicle scheduling, route optimisation, fuel consumption tracking, and driver performance reports. Python/PostgreSQL backend.',90000.00,'2026-12-01 00:00:00.000','EXPERT','OPEN','2026-08-24 16:12:39.943','2026-08-24 16:12:39.943'),(54,52,11,'Production Tracking System for Steel Fabrication','Build a custom production tracking desktop + web application for SteelFab Engineering. Features: job order management, machine utilisation tracking, quality inspection checklists, raw material inventory, and daily production reports.',75000.00,'2026-11-30 00:00:00.000','INTERMEDIATE','OPEN','2026-08-24 16:12:39.956','2026-08-24 16:12:39.956'),(55,25,11,'Real Estate CRM with Automated Follow-Up','Develop a custom CRM for Edge Realty Services with automated lead capture from 99acres and MagicBricks, WhatsApp follow-up bot, site visit scheduling, deal pipeline management, and a commission tracker for agents.',65000.00,'2026-11-15 00:00:00.000','INTERMEDIATE','OPEN','2026-08-24 16:12:39.972','2026-08-24 16:12:39.972'),(56,22,11,'Port Logistics Workflow Digitisation','Digitise cargo clearance and vessel scheduling workflows for Visakha Port Logistics. Build a web app replacing paper-based processes with digital forms, role-based approval chains, document management, and EDI integration with shipping lines.',110000.00,'2027-01-15 00:00:00.000','EXPERT','OPEN','2026-08-24 16:12:39.987','2026-08-24 16:12:39.987'),(57,11,11,'Real Estate Property Listing & CRM System','Build a property listing platform and integrated CRM for Nexus Properties Pvt. Ltd. with geo-search, virtual tour embeds, lead scoring, email drip campaigns, and an interactive analytics dashboard for the sales team.',80000.00,'2026-12-01 00:00:00.000','EXPERT','OPEN','2026-08-24 16:12:40.002','2026-08-24 16:12:40.002'),(58,9,12,'Investment Platform Business Requirements Document','Prepare a comprehensive Business Requirements Document (BRD) for BlueChip Invest Advisory platform upgrade. Deliverables: as-is vs to-be process maps, functional and non-functional requirements, SEBI compliance checklist, and UAT test plan.',30000.00,'2026-10-01 00:00:00.000','EXPERT','OPEN','2026-08-24 16:12:40.018','2026-08-24 16:12:40.018'),(59,10,12,'Edtech Growth Strategy & Market Analysis','Conduct a market analysis and produce a 12-month growth strategy document for SparkLearn Institute covering competitive landscape, student acquisition cost benchmarks, geographic expansion plan, and revenue model optimisation recommendations.',25000.00,'2026-10-20 00:00:00.000','EXPERT','OPEN','2026-08-24 16:12:40.028','2026-08-24 16:12:40.028'),(60,32,12,'Solar Energy Project Financial Modelling','Build a detailed financial model in Excel/Python for SolarPlus Energy evaluating ROI for C&I rooftop solar projects across Gujarat. Model must include capex/opex breakdown, IRR, payback period, sensitivity analysis, and subsidy impact.',35000.00,'2026-10-25 00:00:00.000','EXPERT','OPEN','2026-08-24 16:12:40.037','2026-08-24 16:12:40.037'),(61,13,12,'Pharma Distribution Process Optimisation','Analyse current distribution processes for PharmaBridge Distributors and recommend optimisations to reduce order fulfilment time by 40%. Deliverables: process maps, root cause analysis, SOP documentation, and a KPI tracking dashboard.',28000.00,'2026-11-01 00:00:00.000','INTERMEDIATE','OPEN','2026-08-24 16:12:40.049','2026-08-24 16:12:40.049'),(62,2,11,'Build a customer insight dashboard','Great Skills',5000.00,'2026-09-30 00:00:00.000','INTERMEDIATE','OPEN','2026-09-10 16:35:25.410','2026-09-10 16:35:25.410');
